        } else {
            luma = 0.2126 * r + 0.7152 * g + 0.0722 * b
        }
    }

    /// Metal's `smoothstep`, Hermite.
    static func smoothstep(_ e0: Double, _ e1: Double, _ x: Double) -> Double {
